import React from 'react';
import Main from '../components/adminDashboard/main/Main'; // 1. Uncomment this import
import Sidebar from "../components/adminDashboard/sidebar/Sidebar";
import './adminDashboard.css'; // 2. Import CSS for layout

const AdminDashboard = () => {
  return (
    // 3. Use CSS classes for a flexible layout
    <div className="admin-dashboard">
      <div className="admin-dashboard__sidebar">
        <Sidebar />
      </div>
      <div className="admin-dashboard__main">
        <Main />
      </div>
    </div>
  );
}

export default AdminDashboard;
